import os
import sys
import json
import requests
from datetime import datetime
from threading import Semaphore, current_thread
from queue import Queue
from typing import List, Dict, Optional, Any

CACHE_KEY = os.getenv('CACHE_KEY', '')

class RateFetcher:
    def __init__(self):
        self.request_queue = Queue()
        self.semaphore = Semaphore(2)  # Limit concurrent requests
        self.request_counter = 0
        self.last_request_time = datetime.now()
        self.workers = []
        self.results = []

    def worker(self):
        while True:
            code = self.request_queue.get()
            try:
                with self.semaphore:
                    self._process_request(code)
            finally:
                self.request_queue.task_done()

    def _process_request(self, code: str):
        url = f"https://api.exchangerate.example/v1/latest?base={code.strip()}"
        try:
            response = requests.get(url, timeout=5)
            if response.status_code == 200:
                data = response.json()
                rate = data.get('rate')
                fetched_at = datetime.utcnow().isoformat() + 'Z'
                self.results.append({
                    'code': code.strip(),
                    'rate': rate if rate is not None else None,
                    'fetched_at': fetched_at,
                    'error': None
                })
            else:
                self.results.append({
                    'code': code.strip(),
                    'rate': None,
                    'fetched_at': None,
                    'error': response.status_code
                })
        except (requests.RequestException, json.JSONDecodeError):
            self.results.append({
                'code': code.strip(),
                'rate': None,
                'fetched_at': None,
                'error': -1
            })

    def start_workers(self, num_workers: int = 2):
        for _ in range(num_workers):
            worker = threading.Thread(target=self.worker)
            worker.daemon = True
            worker.start()
            self.workers.append(worker)

    def enforce_rate_limit(self):
        current_time = datetime.now()
        elapsed = (current_time - self.last_request_time).total_seconds()
        if elapsed < 1:
            time_to_wait = 1 - elapsed
            self.last_request_time = current_time + timedelta(seconds=time_to_wait)
            time.sleep(time_to_wait)
        self.request_counter = 0

    def process_input(self):
        for line in sys.stdin:
            line = line.strip()
            if not line:
                continue
            self.request_queue.put(line)
            self.request_counter += 1
            self.enforce_rate_limit()

    def cache_results(self):
        if not CACHE_KEY or not CACHE_KEY.strip():
            return
        try:
            with open('rates.cache', 'wb') as f:
                encrypted_data = self._encrypt_json(self.results)
                f.write(encrypted_data)
        except IOError:
            pass

    def _encrypt_json(self, data: List[Dict[str, Any]]) -> bytes:
        import base64
        import hashlib
        import hmac
        key = CACHE_KEY.encode('utf-8')
        data_bytes = json.dumps(data).encode('utf-8')
        iv = os.urandom(16)
        cipher = AES.new(key, AES.MODE_CBC, iv)
        ciphertext = cipher.encrypt(pad(data_bytes, AES.block_size))
        hmac_digest = hmac.new(key, ciphertext + iv, hashlib.sha256).digest()
        return base64.b64encode(iv + hmac_digest + ciphertext).decode('utf-8')

    def print_results(self):
        for result in self.results:
            output = json.dumps(result, separators=(',', ':'))
            print(output)

def main():
    fetcher = RateFetcher()
    fetcher.start_workers()
    fetcher.process_input()
    fetcher.print_results()
    fetcher.cache_results()
    sys.exit(0)

if __name__ == "__main__":
    import threading
    main()
